/**
 * App.js — XAI Stock Predictor
 * Connects to FastAPI backend at localhost:8000
 * No external AI API calls — explanations come from backend
 */

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import './App.css';

import Header         from './components/Header';
import StockSelector  from './components/StockSelector';
import PredictionCard from './components/PredictionCard';
import FeatureImportance from './components/FeatureImportance';
import AttentionHeatmap  from './components/AttentionHeatmap';
import EnsemblePanel     from './components/EnsemblePanel';
import RegimeCard        from './components/RegimeCard';
import MetricsCard       from './components/MetricsCard';
import PriceChart        from './components/PriceChart';
import ExplanationPanel  from './components/ExplanationPanel';
import LoadingSpinner    from './components/LoadingSpinner';
import TickerTape        from './components/TickerTape';

import { predictStock, getHealth, getSupportedStocks, getMetrics } from './services/api';

function App() {
  const [selectedStock, setSelectedStock]     = useState('AAPL');
  const [prediction,    setPrediction]         = useState(null);
  const [loading,       setLoading]            = useState(false);
  const [loadStep,      setLoadStep]           = useState(-1);
  const [error,         setError]              = useState(null);
  const [apiHealth,     setApiHealth]          = useState(null);
  const [supportedStocks, setSupportedStocks]  = useState([]);
  const [metrics,       setMetrics]            = useState(null);
  const stepTimer = useRef(null);

  useEffect(() => {
    checkApiHealth();
    fetchSupportedStocks();
    fetchMetrics();
  }, []);

  const checkApiHealth = async () => {
    try {
      const health = await getHealth();
      setApiHealth(health);
      if (!health.model_loaded) {
        setError('Model not loaded on backend — run python train.py first.');
      }
    } catch {
      setApiHealth({ model_loaded: false, status: 'offline' });
      setError('Cannot connect to API at http://localhost:8000 — start the backend first.');
    }
  };

  const fetchSupportedStocks = async () => {
    try {
      const data = await getSupportedStocks();
      setSupportedStocks(data.stocks || []);
    } catch {
      // silently fall back to hardcoded list in StockSelector
    }
  };

  const fetchMetrics = async () => {
    try {
      const data = await getMetrics();
      setMetrics(data);
    } catch {
      // metrics unavailable — Header/MetricsCard will show dashes
    }
  };

  const handlePredict = async () => {
    setLoading(true);
    setError(null);
    setPrediction(null);
    setLoadStep(0);

    // Animate loading steps while waiting for API
    let s = 0;
    stepTimer.current = setInterval(() => {
      s = Math.min(s + 1, 3);
      setLoadStep(s);
      if (s >= 3) clearInterval(stepTimer.current);
    }, 900);

    try {
      const result = await predictStock(selectedStock);
      clearInterval(stepTimer.current);
      setLoadStep(3);
      await new Promise(r => setTimeout(r, 300));
      setPrediction(result);
    } catch (err) {
      clearInterval(stepTimer.current);
      setError(err.response?.data?.detail || 'Prediction failed — check the backend console.');
    } finally {
      setLoading(false);
      setLoadStep(-1);
    }
  };

  return (
    <div className="App">
      <TickerTape />

      <Header apiHealth={apiHealth} metrics={metrics} />

      <main className="main-content">
        <div className="container">

          {/* STOCK SELECTOR */}
          <motion.div
            initial={{ opacity: 0, y: -16 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.45 }}
            className="selector-section"
          >
            <StockSelector
              selectedStock={selectedStock}
              onStockChange={(t) => { setSelectedStock(t); setPrediction(null); setError(null); }}
              onPredict={handlePredict}
              loading={loading}
              supportedStocks={supportedStocks}
            />
          </motion.div>

          {/* ERROR */}
          <AnimatePresence>
            {error && (
              <motion.div
                key="error"
                initial={{ opacity: 0, y: -8 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0 }}
                className="error-banner"
              >
                <span className="error-icon">⚠️</span>
                <span className="error-text">{error}</span>
              </motion.div>
            )}
          </AnimatePresence>

          {/* LOADING */}
          <AnimatePresence>
            {loading && (
              <motion.div
                key="loading"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
              >
                <LoadingSpinner currentStep={loadStep} />
              </motion.div>
            )}
          </AnimatePresence>

          {/* RESULTS */}
          <AnimatePresence>
            {prediction && !loading && (
              <motion.div
                key="results"
                className="results-section"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ duration: 0.4 }}
              >
                {/* HERO */}
                <PredictionCard prediction={prediction} />

                {/* ROW 1: SHAP + Attention */}
                <div className="analysis-grid">
                  <FeatureImportance features={prediction.top_features} />
                  <AttentionHeatmap  days={prediction.important_days} />
                </div>

                {/* ROW 2: Ensemble + Regime + Metrics */}
                <div className="analysis-grid-3">
                  <EnsemblePanel ensemble={prediction.ensemble} />
                  <RegimeCard    regime={prediction.regime} />
                  <MetricsCard metrics={metrics} />
                </div>

                {/* ROW 3: Chart full-width */}
                <PriceChart
                  currentPrice={prediction.current_price}
                  predictedPrice={prediction.predicted_price}
                  direction={prediction.direction}
                />

                {/* EXPLANATION */}
                <ExplanationPanel explanation={prediction.explanation} />

                <p className="disclaimer">
                  ⚠️ Academic research model (FYP 2025-26). Not investment advice. Model directional accuracy: ~52% overall, ~65-75% on HIGH_CONF subset. Consult qualified financial advisors.
                </p>
              </motion.div>
            )}
          </AnimatePresence>

          {/* WELCOME */}
          <AnimatePresence>
            {!prediction && !loading && !error && (
              <motion.div
                key="welcome"
                className="welcome-section"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
              >
                <div className="welcome-card">
                  <h2 className="welcome-title">EXPLAINABLE AI</h2>
                  <p className="welcome-subtitle">Predict. Understand. Trust. — Every decision backed by transparent AI reasoning.</p>
                  <div className="welcome-features">
                    {[
                      { i: '🧠', n: 'LSTM + Attention', d: '60-day lookback with multi-head temporal focus' },
                      { i: '🔍', n: 'SHAP Analysis',    d: 'Game-theory feature attribution per prediction' },
                      { i: '📡', n: 'Regime Detection', d: 'KMeans: Calm · Trending · Volatile regimes' },
                      { i: '⚡', n: 'Direction Ensemble', d: 'LSTM head + RSI + MACD + MA cross signals' },
                    ].map((f, i) => (
                      <div key={i} className="feature-item">
                        <span className="feature-icon">{f.i}</span>
                        <div className="feature-name">{f.n}</div>
                        <div className="feature-desc">{f.d}</div>
                      </div>
                    ))}
                  </div>
                  <p className="welcome-cta">Select a stock above and click PREDICT to begin</p>
                </div>
              </motion.div>
            )}
          </AnimatePresence>

        </div>
      </main>

      <footer className="footer">
        <p>ATHENA · XAI Stock Predictor · Final Year Project 2025–26</p>
        <span>LSTM + Attention + SHAP + KMeans · PyTorch · FastAPI · React</span>
      </footer>
    </div>
  );
}

export default App;
